mapper.select:
SELECT * FROM (
SELECT * , ROWNUM FROM ( SELECT MNG.* , ( SELECT CASE WHEN LOCGOV.LOCGOV_CODE = LOCGOV.UPPER_LOCGOV_CODE THEN LOCGOV.UPPER_LOCGOV_NM ELSE CONCAT(LOCGOV.UPPER_LOCGOV_NM, ' ', LOCGOV.LOCGOV_NM) END FROM G_LOCGOV LOCGOV WHERE LOCGOV.LOCGOV_CODE = MNG.LOCGOV_CODE) AS LOCGOV_NM FROM ( SELECT SPCL_ITEM_MNG_ID , LOCGOV_CODE , SPCL_ITEM_INFO , FRST_REGIST_PNTTM , ( SELECT GROUP_CONCAT(SPCL_ITEM_KEYWORD) FROM (SELECT SPCL_ITEM_KEYWORD FROM G_SPCL_ITEM_MNG_KEYWORD WHERE SPCL_ITEM_MNG_ID = MNG.SPCL_ITEM_MNG_ID ORDER BY REG_SEQ) ) AS KEYWORDS FROM G_SPCL_ITEM_MNG MNG WHERE 1=1
AND MNG.LOCGOV_CODE = #{locgovCode}
AND MNG.LOCGOV_CODE IN ( SELECT LOCGOV.LOCGOV_CODE FROM G_LOCGOV LOCGOV WHERE LOCGOV.UPPER_LOCGOV_CODE = #{upperLocgovCode} )
AND MNG.LOCGOV_CODE = #{locgovCode}
AND MNG.SPCL_ITEM_MNG_ID = #{specialityItemManageId}
AND MNG.SPCL_ITEM_MNG_ID IN ( SELECT SPCL_ITEM_MNG_ID FROM G_SPCL_ITEM_MNG_KEYWORD WHERE SPCL_ITEM_KEYWORD LIKE CONCAT('%', #{keywords}, '%') )
) MNG LEFT OUTER JOIN OP_COMMON_CODE CD ON CODE_TYPE = 'WDR' AND ID = MNG.LOCGOV_CODE GROUP BY SPCL_ITEM_MNG_ID ORDER BY LOCGOV_NM ) )

mapper.insert:
INSERT INTO G_SPCL_ITEM_MNG
	(
		SPCL_ITEM_MNG_ID
		, LOCGOV_CODE
		, SPCL_ITEM_INFO

		, FRST_REGISTER_ID
		, FRST_REGIST_PNTTM
		, LAST_UPDUSR_ID
		, LAST_UPDT_PNTTM
	)
	VALUES
	(
		#{specialityItemManageId}
		, #{locgovCode}
		, #{specialityItemInfo}

		, #{frstRegisterId}
		, #{frstRegistPnttm}
		, #{lastUpdusrId}
		, #{lastUpdtPnttm}
	)

mapper.update:
UPDATE G_SPCL_ITEM_MNG
	SET SPCL_ITEM_INFO = #{specialityItemInfo}

		, LAST_UPDUSR_ID = #{lastUpdusrId}
		, LAST_UPDT_PNTTM = #{lastUpdtPnttm}
	WHERE
		SPCL_ITEM_MNG_ID = #{specialityItemManageId}

