INSERT INTO G_SPCL_ITEM
	(
		SPCL_ITEM_MNG_ID
		, ITEM_ID
		, DISPLAY_ORDER
		, FRST_REGISTER_ID
		, FRST_REGIST_PNTTM
		, LAST_UPDUSR_ID
		, LAST_UPDT_PNTTM
	)
	VALUES
	(
		#{specialityItemManageId}
		, #{itemId}
		, #{displayOrder}
		, #{frstRegisterId}
		, #{frstRegistPnttm}
		, #{lastUpdusrId}
		, #{lastUpdtPnttm}
	)

INSERT INTO G_SPCL_ITEM_MNG_KEYWORD
	(
		SPCL_ITEM_MNG_ID
		, SPCL_ITEM_KEYWORD
		, REG_SEQ
		, FRST_REGISTER_ID
		, FRST_REGIST_PNTTM
		, LAST_UPDUSR_ID
		, LAST_UPDT_PNTTM
	)
	VALUES
	(
		#{specialityItemManageId}
		, #{keywords}
		, #{regSeq}
		, #{frstRegisterId}
		, #{frstRegistPnttm}
		, #{lastUpdusrId}
		, #{lastUpdtPnttm}
	)

